import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'

import { lemonToast } from '@posthog/lemon-ui'

import { ApiError } from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

import { commentsLinkSlackThreadCreate } from 'products/platform_features/frontend/generated/api'

import { CommentsLogicProps, commentsLogic } from './commentsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linkSlackThreadLogicValues {
    currentProjectId: number | string // teamLogic
    error: string | null
    integrationId: number | null
    isOpen: boolean
    isSubmitting: boolean
    url: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linkSlackThreadLogicActions {
    incrementCommentCount: () => any // commentsLogic
    refreshComments: () => {
        value: true
    } // commentsLogic
    closeModal: () => {
        value: true
    }
    openModal: () => {
        value: true
    }
    setIntegrationId: (integrationId: number | null) => {
        integrationId: number | null
    }
    setUrl: (url: string) => {
        url: string
    }
    submit: () => {
        value: true
    }
    submitFailure: (detail?: string | null) => {
        detail: string | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linkSlackThreadLogicMeta {
    key: string
}

export type linkSlackThreadLogicType = MakeLogicType<
    linkSlackThreadLogicValues,
    linkSlackThreadLogicActions,
    CommentsLogicProps,
    linkSlackThreadLogicMeta
>

// Keyed like commentsLogic, so the modal belongs to the discussion whose composer opened it and two
// discussion panels on screen at once can't both answer one click.
export const linkSlackThreadLogic = kea<linkSlackThreadLogicType>([
    props({} as CommentsLogicProps),
    key((props) => `${props.scope}-${props.item_id || ''}`),
    path((key) => ['lib', 'components', 'Comments', 'linkSlackThreadLogic', key]),
    connect((props: CommentsLogicProps) => ({
        values: [teamLogic, ['currentProjectId']],
        actions: [commentsLogic(props), ['refreshComments', 'incrementCommentCount']],
    })),
    actions({
        openModal: true,
        closeModal: true,
        setIntegrationId: (integrationId: number | null) => ({ integrationId }),
        setUrl: (url: string) => ({ url }),
        submit: true,
        submitFailure: (detail: string | null = null) => ({ detail }),
    }),
    reducers({
        isOpen: [
            false,
            {
                openModal: () => true,
                closeModal: () => false,
            },
        ],
        integrationId: [
            null as number | null,
            {
                setIntegrationId: (_, { integrationId }) => integrationId,
                openModal: () => null,
            },
        ],
        url: [
            '',
            {
                setUrl: (_, { url }) => url,
                openModal: () => '',
            },
        ],
        // Kept in the modal rather than toasted: PostHog's refusal says what to fix (a link from a
        // shared channel, a channel the bot isn't in, a thread that already syncs), and the fix is to
        // paste a different link into the field the reason sits under.
        error: [
            null as string | null,
            {
                submitFailure: (_, { detail }) => detail ?? 'Could not link the Slack thread',
                setUrl: () => null,
                setIntegrationId: () => null,
                openModal: () => null,
            },
        ],
        isSubmitting: [
            false,
            {
                submit: () => true,
                submitFailure: () => false,
                openModal: () => false,
                closeModal: () => false,
            },
        ],
    }),
    listeners(({ actions, values, props }) => ({
        submit: async () => {
            const { integrationId, url, currentProjectId } = values
            if (!props.item_id || !integrationId || !url.trim() || !currentProjectId) {
                actions.submitFailure()
                return
            }
            try {
                // The comments API is project-scoped — currentTeamId diverges from the project id
                // for non-default environments and 404s.
                await commentsLinkSlackThreadCreate(String(currentProjectId), {
                    scope: props.scope,
                    item_id: props.item_id,
                    integration_id: integrationId,
                    url: url.trim(),
                })
            } catch (e) {
                actions.submitFailure(e instanceof ApiError ? e.detail : null)
                return
            }
            // A refresh rather than a load: the opening comment is dated when it was sent in Slack,
            // so it can land mid-list, and a load would scroll the reader to the bottom instead.
            actions.refreshComments()
            actions.incrementCommentCount()
            actions.closeModal()
            lemonToast.success('Slack thread linked. Its earlier replies follow in a moment')
        },
    })),
])
